from layout import *

def study_design():
    page('Методы','Как устроено сравнение','У каждого опыта свой проверяемый исход. В поиске это найденная строка исходника, в работе с API — совпадение предсказания с результатом исполнения, в симуляторе — полностью собранный ответ и расход чтений.')
    tbl(['Опыт','Единица и объём','Контроль','Что фиксировано'],[
        ['Поиск','12 символов × 3 условия на каждую из двух моделей','Сырой журнал с теми же фактами','Модуль, расположение цели, варианты команд, один поиск'],
        ['Перенос пробы','6 семейств × 2 версии × 3 условия','Новая проба и обычный прошлый пример','Описание API, одно обращение к цели, четыре проверочных входа'],
        ['Память о стоимости','64 мира, 3 режима зависимости, 128 тестовых заданий на режим','Частоты, целые блоки, давность, выбор по validation','Одинаковые запросы, 8 слотов, максимум 2 чтения'],
        ['Естественные журналы','12 проектов × 4 траектории VibeMemBench','Сверка с оригинальными ответами','Снимок набора, правило отбора и распознаватель shell-команд']
    ],[3.0,4.3,4.55,5.25],True)
    h('Изоляция условий')
    p('Формирователь памяти работает с разрешённым прошлым. Решатель получает текст конкретного эпизода и доступные действия. Каждый вызов Codex начинается в новом пустом временном каталоге с режимом read-only, без истории родительского чата и пользовательской конфигурации. Инструкция запрещает самостоятельные внешние инструменты. Среда отдельно исполняет возвращённое действие и записывает результат. В журналах проверяются события использования инструментов.')
    h('Фиксация и остановка')
    p('Генераторы, входы, правила сравнения и хеши фиксировались локально до экспериментальных ответов каждого стенда. Сеанс с нейтральным ответом проверял только транспорт. После первого пилота отдельно зафиксированы две репликации — вторая модель на тех же задачах поиска и реальные релизы пакетов для переноса пробы. Новых независимых задач вторая модель не добавляет.')
    h('Единицы неопределённости')
    p('Доли и направления расхождения показываются по сопоставленным задачам. Для шести семейств API учтена совместная обработка трёх разных случаев в одном запросе. В симуляции доверительные интервалы строятся по целым мирам. Хронологические данные из открытых репозиториев дают описательную оценку частоты явления в выборке.')

def search_pages():
    a=J('search/results.json');b=J('search_replication/results.json')
    page('Опыт 1   /   навигация по коду','Что запомнить после поиска','До обращения к модели стенд выполнил четыре поиска, по одному в каждом каталоге. Агенту разрешён один следующий запрос. Можно ли по журналу понять, где определение ещё могло остаться?')
    p('В 12 наборах находится по одному целому исходному модулю CPython 3.14.4. Каталоги и дополнительные файлы со ссылками на символ построены экспериментатором. Для каждого символа доступны четыре команды ripgrep, по одной на каталог. Проверяющий исполняет выбранную команду и сопоставляет путь и номер строки с эталонным определением. Снимок между сессиями не меняется.')
    p('Заданы четыре причины неполного поиска — рабочая директория, маска имени файла, исключение скрытых каталогов и ограничение числа показанных строк. Для восьми символов по журналу остаётся один разумный каталог, для четырёх — два. Правильная буква команды и каталог сбалансированы. Короткое резюме описывает отсутствие показанного определения. Сырой журнал и карточка содержат одинаковые аргументы, каталог, код завершения, показанные строки и метаданные лимита. Преобразование полей проверено обратной конвертацией.')
    rows=[]
    for model,res in [('GPT-6.1-sol',a),('GPT-6-luna',b)]:
        for k,l in [('summary','Короткая запись'),('raw','Сырой журнал'),('structured','Карточка')]:
            z=res['arms'][k];rows.append([model,l,str(z['pass_count'])+'/12',str(z['unresolved_choice_count'])+'/12',n(z['median_memory_chars'])])
    tbl(['Модель','Память','Найдено определение','Выбран возможный каталог','Медиана знаков'],rows,[3.0,4.25,3.15,3.6,3.1],True)
    h('Главный парный контраст')
    for model,res in [('GPT-6.1-sol',a),('GPT-6-luna',b)]:
        v=next(z for z in res['paired_contrasts'] if z['arm_a']=='structured' and z['arm_b']=='raw' and z['measure']=='pass')
        p(f"{model}. Карточка против сырого журнала — {pp(v['mean_paired_difference'])} п.п. Только карточка решила {v['a_only']} задач, только журнал — {v['b_only']}. Точный двусторонний тест Мак-Немара по несовпавшим парам даёт p = {dec(v['exact_two_sided_p'],3)}.")
    p('При независимой случайной выборке 0 расхождений из 12 допускают до 22,1% расхождений (точная односторонняя 95%-я верхняя граница). Здесь задачи отобраны по конструкции. Тесты описательные, эквивалентность не установлена.','Caption')
    page('Опыт 1   /   разбор действий','Где журнал помог и где его не хватило')
    h('compress в bz2.py')
    p('В предыдущем сеансе поиск из трёх подкаталогов шёл по пути «..», а из adapters/surface — по «.». Вызов из adapters/surface охватил только этот подкаталог. С короткой записью GPT-6.1-sol выбрал core и получил пустой ответ. С сырым журналом и карточкой выбрал adapters. Реальный ripgrep вернул объявление def compress в файле adapters/runtime/bz2.py, строка 321.')
    h('_reconstructor в copyreg.py')
    p('В двух каталогах, extensions и adapters, было показано по четыре строки из девяти. Из выдачи нельзя определить, где находилась искомая строка. С обоими богатыми представлениями GPT-6.1-sol выбрал extensions и ничего не нашёл. Объявление находилось в adapters/z_runtime/copyreg.py на строке 46. Такой выбор сохраняет смысл даже при неуспехе. Поэтому измерялись и пригодность следующего поиска, и фактическая локализация.')
    h('Как читать разницу с коротким пересказом')
    v=next(z for z in a['paired_contrasts'] if z['arm_a']=='raw' and z['arm_b']=='summary' and z['measure']=='pass')
    p(f"У первой модели сырой журнал дал {v['a_only']} дополнительных успехов и {v['b_only']} обратных переходов относительно пересказа. Парная разность {pp(v['mean_paired_difference'])} п.п., p = {dec(v['exact_two_sided_p'],4)}. Условия различаются количеством фактов и длиной сообщения. Только сравнение карточки с журналом изолирует эффект представления при одинаковых фактах.")
    h('Цена')
    rows=[]
    for model,res in [('Sol',a),('Luna',b)]:
        for arm,label in [('summary','Пересказ'),('raw','Сырой журнал'),('structured','Карточка')]:
            z=res['arms'][arm];rows.append([model,label,n(z['input_tokens']),n(z['cached_input_tokens']),n(z['output_tokens']),dec(z['median_model_seconds'],2)])
    tbl(['Модель','Условие','Вход, всего','Из них из кэша','Выход','Медиана, с'],rows,[2.0,3.7,3.1,3.3,2.4,2.6],True)
    p('В токены входит системный контекст Codex CLI. Токены кэша уже входят во вход. Длительность зависит также от сервера и параллельного запуска. Тарифы и стоимость подписки не оценивались.','Caption')

def field_page():
    d=J('field/summary.json');s=d['total']
    page('Внешние данные   /   проверка предпосылки','Как часто поиск действительно ограничивают','В 33 из 48 открытых историй агент хотя бы раз поставил явный предел выдачи поиска. Для одного вызова удалось воспроизвести все совпадения и точно установить, какие строки оказались за этим пределом.')
    p('Использован зафиксированный снимок VibeMemBench. Исключены восемь проектов прежнего обзора. Среди оставшихся Python-проектов с четырьмя и более историями выбраны 12 по хешу с заданным seed, затем по четыре истории в каждом. Результаты поиска сопоставлены с ответами shell-инструмента по идентификаторам. Все 48 исходных файлов оказались доступны.')
    tbl(['Что найдено','Количество','Смысл'],[
        ['Истории с распознанным текстовым поиском','46 / 48','Обнаружен хотя бы один простой вызов grep, rg или git grep'],
        ['Истории с пределом выдачи','33 / 48 (68,75%)','Лимит задан в команде, его достижение проверено отдельно'],
        ['Поисковые команды с пределом','137 / 444','Все 137 оказались конвейерами с head'],
        ['Ответ выдачи короче / равен лимиту','97 / 40','Лимит достигнут в 20 из 48 историй'],
        ['Дословно повторена команда','5 / 48 историй','6 повторов, полезность повторения неизвестна']
    ],[6.15,3.3,7.65],True)
    h('Строго проверенный случай')
    p('В eodag-616 ранее был прочитан полный файл qssearch.py, 1 222 строки. В следующем поиске grep передавал результат в head -80. На зафиксированном содержимом файла нашлось 110 совпадающих строк. Первые 80 совпали с выдачей посимвольно, ещё 30 остались за пределом. Между чтением и вызовом поиска в журнале отсутствуют действия изменения файла.')
    h('Что можно обобщить')
    p('Парсер специально узкий. Многострочные скрипты, произвольные конвейеры и встроенные в Python поиски остаются за пределами подсчёта. Других сопоставленных shell-вызовов было 2 634. Явный head показывает, что контроль полноты бывает нужен в реальной работе. Из частоты таких команд нельзя вывести частоту ошибочных решений, потребность в передаче между агентами или выигрыш карточки.')
    source('Снимок VibeMemBench и исходные траектории','https://huggingface.co/datasets/Tongyi-ConvAI/VibeMemBench/tree/11164976b4f920cdb0d0cd570ca572e49acea1e8')

def probe_pages():
    j=J('probe/summary.json');r=j['counts'];cases=J('probe/scores.json')
    page('Опыт 2   /   перенос между версиями инструмента','Нужен ли сохранённый проверочный пример','Агент может запомнить вход, на котором две прежние версии API вели себя по-разному. Позднее ему разрешена одна проба новой реализации. Эксперимент проверяет, учтёт ли он сохранённый опыт и верно ли предскажет поведение на других входах.')
    p('Шесть семейств функций обрабатывают числа, строки, даты и границы диапазонов. Формирователь карточки видит результаты двух прошлых версий и выбирает различающий вход до показа новой цели. Обычный пример берётся из тех же старых журналов по частоте. Для каждого семейства новая версия либо сохраняет последнее поведение, либо возвращается к другой исторической семантике. Будущие входы не предъявляются при выборе пробы.')
    p('В трёх условиях агент может выбрать собственную пробу. После её исполнения он видит фактический ответ и предсказывает четыре скрытых значения. Успех задачи требует четырёх точных совпадений типа и значения. При батчировании три разных семейства получают один запрос, повторные версии одного семейства не показываются вместе. Пробу и окончательное решение разделяют два вызова модели.')
    rows=[]
    for arm,lab in [('discriminating','Различающий пример'),('ordinary','Обычный пример'),('fresh','Проба с нуля')]:
        v=r[arm];rows.append([lab,f"{v['perfect']}/12",f"{v['correct_outputs']}/48",f"{v['discriminating_actions']}/12",f"{j['stable_or_reverted']['True'][arm]}/6",f"{j['stable_or_reverted']['False'][arm]}/6"])
    tbl(['Память','Полностью верно','Верные значения','Различающая проба','Стабильная версия','Возврат версии'],rows,[3.85,2.65,2.45,2.8,2.6,2.75],True)
    h('Размер эффекта и причина ошибки')
    p('Сохранённый различающий пример против новой пробы дал −8,3 п.п. С карточкой один исход оказался лучше, два хуже, девять совпали. В двух непересекающихся панелях из разных семейств и пакетов запросов разности составили −16,7 и 0 п.п. При удалении по одному семейству диапазон от −10 до 0 п.п. Эти диапазоны — анализ чувствительности. Двух панелей недостаточно для содержательного доверительного интервала по популяции инструментов.')
    p('В задаче bucket запись «−21 → 0» показывала поведение на отрицательном входе. Агент выбрал пробу «110 → 11», которая не различала способы обработки отрицательных входов. Он предсказал 0 для −12, а исполняемая функция вернула −2. Точное повторение сохранённой различающей пробы произошло только в 1 из 12 случаев этого условия.')
    source('Ближайшая работа по памяти об инструментах — ToolAtlas',ar('2607.11126'))

